// 1. 可辨识联合（Discriminated Union）
interface Circle { kind: 'circle'; radius: number }
interface Square { kind: 'square'; side: number }
interface Triangle { kind: 'triangle'; base: number; height: number }
type Shape = Circle | Square | Triangle;

function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle':
      return Math.PI * shape.radius ** 2;  // 收窄为 Circle
    case 'square':
      return shape.side ** 2;              // 收窄为 Square
    case 'triangle':
      return (shape.base * shape.height) / 2;
    default:
      const _exhaustive: never = shape;    // 漏分支时编译报错
      return _exhaustive;
  }
}

// 2. unknown 必须先收窄再使用
function processInput(input: unknown): string {
  // input.toUpperCase();  // 编译错误！
  if (typeof input === 'string') {
    return input.toUpperCase();  // 收窄为 string
  }
  if (typeof input === 'number') {
    return input.toFixed(2);     // 收窄为 number
  }
  throw new TypeError('Expected string or number');
}

// 3. 自定义类型守卫
function isShape(obj: unknown): obj is Shape {
  return (
    typeof obj === 'object' &&
    obj !== null &&
    'kind' in obj &&
    typeof (obj as any).kind === 'string'
  );
}

// 4. const 断言
const ROUTES = {
  home: '/',
  about: '/about',
  user: '/user',
} as const;
// ROUTES.home 的类型是 '/' 而非 string
// typeof ROUTES 是 { readonly home: '/'; readonly about: '/about'; readonly user: '/user' }

type Route = (typeof ROUTES)[keyof typeof ROUTES];
// 结果: '/' | '/about' | '/user'

// 5. 枚举替代方案（零运行时开销）
const STATUS = {
  Idle: 'idle',
  Loading: 'loading',
  Success: 'success',
  Error: 'error',
} as const;
type Status = (typeof STATUS)[keyof typeof STATUS];
// 'idle' | 'loading' | 'success' | 'error'
